// Generated from contracts/task_spec.schema.json by `make contracts`. Do not edit.

export type Tier = "novice" | "adept" | "master";
export type Kind = "domain" | "dsa";
/**
 * Relative POSIX path inside the task repo. No leading slash, no . or .. segments.
 */
export type RelPath = string;
/**
 * A name valid in both Python and JavaScript.
 */
export type Identifier = string;

/**
 * Full specification of one assessment task. BACKEND ONLY: contains the reference solution pointer, hidden tests and certificate. The browser gets CandidateTaskView instead.
 */
export interface TaskSpec {
  task_id: string;
  /**
   * Revision of this task; bumped whenever the spec changes.
   */
  version: number;
  tier: Tier;
  kind: Kind;
  /**
   * seed: built from a hand-written seed repo or the DSA bank. llm: generated by the generator model.
   */
  mode: "seed" | "llm";
  /**
   * Seed repo or DSA bank entry the task was built from. Null when mode is llm.
   */
  seed_id: string | null;
  /**
   * Runtime id: a directory under runtimes/ (python311, node20). The runner image is assess-<id>.
   */
  runtime: string;
  /**
   * DSA topics exercised (same names as Portfolio.assessment.dsaTopicsSolved). Empty for domain tasks.
   */
  dsa_tags: string[];
  /**
   * Task statement shown to the candidate (Markdown).
   */
  statement_md: string;
  /**
   * Orientation to the starter repo (Markdown). Empty for DSA tasks.
   */
  repo_tour_md: string;
  starter_files: FileMap;
  /**
   * Pointer to the reference solution in backend storage. Never the solution itself.
   */
  reference_ref: string;
  /**
   * Symbols the solution must change, as path::qualname.
   */
  target_symbols: string[];
  /**
   * Symbols where a candidate should start reading, as path::qualname.
   */
  entry_symbols: string[];
  visible_tests: TestFile[];
  hidden_tests: TestFile[];
  /**
   * Exact set of test ids (e.g. pytest node ids) the runner must collect from visible_tests, recorded when the task is built. Any other set means the run is not trusted: status error, reason test_set_mismatch.
   */
  visible_test_ids: string[];
  /**
   * Same as visible_test_ids, for hidden_tests.
   */
  hidden_test_ids: string[];
  /**
   * Test ids that fail on the starter (the reference passes every test), recorded by the validation gate (backend/gate). Absent or null before the gate ran.
   */
  fail_to_pass?: TestIdSplit | null;
  /**
   * Test ids that already pass on the starter, recorded by the validation gate. Absent or null before the gate ran.
   */
  pass_to_pass?: TestIdSplit | null;
  /**
   * Input/expected cases for DSA tasks. Null for domain tasks. For bank problems, hidden is the pool a session's hidden sample is drawn from (see SubmitPayload.hidden_sample).
   */
  dsa_cases: DsaCases | null;
  /**
   * DSA bank problems: how the bank's function and parameter names were renamed for this task (seed_id is the bank problem id). Case inputs use the renamed parameters. Absent or null for domain tasks and the P1.3 demo problem.
   */
  dsa_names?: DsaNames | null;
  /**
   * Performance constraint. Null when the task has none.
   */
  perf: Perf | null;
  time_budget_min: number;
  /**
   * Seeds used for generation, input generators and mutation testing, so the task can be rebuilt exactly.
   */
  random_seeds: number[];
  certificate: Certificate;
  /**
   * Fraction of probe-model attempts that passed all hidden tests.
   */
  ai_solve_rate: number;
  /**
   * Computed difficulty estimate; higher is harder.
   */
  difficulty_index: number;
}
/**
 * Relative path -> file content.
 */
export interface FileMap {
  [k: string]: string;
}
/**
 * A test file. Test ids are the runner's ids for the tests it contains (e.g. pytest node ids).
 */
export interface TestFile {
  path: RelPath;
  content: string;
}
export interface TestIdSplit {
  visible: string[];
  hidden: string[];
}
export interface DsaCases {
  visible: DsaCase[];
  hidden: DsaCase[];
  /**
   * How the backend compares an output with the expected value. Null means exact JSON equality.
   */
  comparator: Comparator | null;
}
/**
 * One DSA test case. input: arguments passed to the entry function; expected: its expected return value. Both may be any JSON value.
 */
export interface DsaCase {
  id: string;
  input: unknown;
  expected: unknown;
}
/**
 * unordered_list: the output and expected lists hold the same items in any order. float_tolerance: numbers may differ by at most tolerance (absolute), everything else exact.
 */
export interface Comparator {
  kind: "exact" | "unordered_list" | "float_tolerance";
  tolerance: number | null;
}
/**
 * 1:1 renaming. parameters is in signature order (the JS harness passes arguments positionally in this order).
 */
export interface DsaNames {
  function: NameMapping;
  parameters: NameMapping[];
}
export interface NameMapping {
  original: Identifier;
  renamed: Identifier;
}
export interface Perf {
  budget_ms: number;
  /**
   * Name of the input generator the runner uses to build the timed input.
   */
  input_gen: string;
}
/**
 * Evidence from the validation gate (backend/gate) that the task is sound. Builders store a draft (booleans); the gate replaces it with counts.
 */
export interface Certificate {
  /**
   * Gate: 'n/n xR', tests (visible + hidden) the reference passed out of the total, the same in each of R runs. Boolean: a builder's draft, or a task stored before P2.7.
   */
  reference_pass: string | boolean;
  /**
   * Gate: 'k/n visible', k of the n visible tests fail on the starter. Boolean: a builder's draft, or a task stored before P2.7.
   */
  starter_fail: string | boolean;
  /**
   * Fraction of reference mutants killed by the hidden tests (gate with mutation testing on). Null when not measured; tasks stored before P2.7 hold a 0.0 placeholder.
   */
  mutation_score: number | null;
  /**
   * DSA: share of cases the weakest trivial stub (first argument, empty value of the return type, 0, None) fails. Null or absent for domain tasks.
   */
  stub_fail_rate?: number | null;
  /**
   * Deprecated, replaced by stub_fail_rate. Kept so tasks stored before P2.7 stay valid.
   */
  bruteforce_agree?: boolean | null;
  /**
   * The task's perf budget (perf.budget_ms). Null or absent when perf is null.
   */
  budget_ms?: number | null;
  /**
   * Domain: lines that differ between the starter and the reference (a replaced line counts once). Null or absent for DSA tasks.
   */
  changed_lines?: number | null;
  /**
   * Reference runtime on the perf input. Null when perf is null.
   */
  perf_ref_ms: number | null;
  /**
   * Naive solution runtime on the perf input. Null when perf is null.
   */
  perf_naive_ms: number | null;
  /**
   * Files the reference solution changes.
   */
  scope_files: RelPath[];
}
